svg.script:
(function () {
  const zonas = Array.from(document.querySelectorAll('.zona-nivel'))
    .sort((a, b) => Number(a.id.replace('nivel-', '')) - Number(b.id.replace('nivel-', '')));
  const DURACION_NIVEL = 5000;
  let indiceActual = 0;
  let temporizador = null;

  function iluminar(zona, avisar = true) {
    zonas.forEach(z => {
      const activo = z === zona;
      z.classList.toggle('activo', activo);
      z.setAttribute('aria-pressed', activo ? 'true' : 'false');
    });
    const nivelActivo = zona.id.replace('nivel-', '');
    document.querySelectorAll('.texto-nivel').forEach(texto => {
      texto.classList.toggle('activo', texto.classList.contains('texto-nivel-' + nivelActivo));
    });
    indiceActual = zonas.indexOf(zona);
    if (avisar) {
      try {
        parent.postMessage({ tipo: 'proto-luma-nivel', nivel: zona.id.replace('nivel-', '') }, '*');
      } catch (e) {}
    }
  }

  function iniciarSecuencia() {
    if (temporizador) clearInterval(temporizador);
    iluminar(zonas[indiceActual] || zonas[0]);
    temporizador = setInterval(() => {
      indiceActual = (indiceActual + 1) % zonas.length;
      iluminar(zonas[indiceActual]);
    }, DURACION_NIVEL);
  }

  zonas.forEach((zona, indice) => {
    zona.addEventListener('click', () => {
      indiceActual = indice;
      iluminar(zona, false);
      // Avisar al documento principal que este toque fue una selección manual.
      try {
        parent.postMessage({ tipo: 'proto-luma-nivel', nivel: zona.id.replace('nivel-', ''), accion: 'seleccionar' }, '*');
      } catch (e) {}
      // Tras tocar un nivel, permanece iluminado y la secuencia continúa
      // desde el siguiente nivel después de cinco segundos.
      if (temporizador) clearInterval(temporizador);
      temporizador = setInterval(() => {
        indiceActual = (indiceActual + 1) % zonas.length;
        iluminar(zonas[indiceActual]);
      }, DURACION_NIVEL);
    });
    zona.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault(); zona.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      }
    });
  });

  iniciarSecuencia();
})();
